      "shortAnswer": "Foreign dividends and rent from overseas property may qualify under Article 20/D when all conditions are met. Each income stream needs independent classification.",
      "bosphorasHelp": "Bosphoras helps prepare your relocation: income inventory, moving timeline, housing and appointments with independent tax specialists. Request a private assessment before moving your residence.",
