          "body": "An eligible resident receives the equivalent of TRY 800,000 in overseas rents, TRY 600,000 in foreign dividends and TRY 300,000 in Turkish rents. If both foreign streams qualify in full, TRY 1.4 million is excluded from the Turkish tax base under the regime. The TRY 300,000 of domestic rent follows ordinary rules before relevant deductions or exemptions. This is not a final estimate of total tax."
