      "shortAnswer": "La Turquie offre une exonération ciblée de revenus étrangers aux nouveaux résidents éligibles. Ce n’est pas un territoire où tout revenu, société ou patrimoine serait imposé à zéro.",
      "bosphorasHelp": "Bosphoras prépare votre projet d’installation : inventaire des revenus, calendrier de déménagement, logement et coordination de rendez-vous avec un fiscaliste indépendant. Demandez une étude privée avant de transférer votre résidence.",
