      "shortAnswer": "وقعت اتفاقية ضريبة الدخل الفرنسية التركية في 18 فبراير 1987 ودخلت حيز التنفيذ في 1 يوليو 1989. توزع حقوق فرض الضرائب ولا تمنح إعفاء عاماً.",
